    func savePlotSpec(name: String, specKind: String, specJson: String, dataSource: String?) throws  -> PlotSpecRow
    
    /**
     * Search artifacts by text across title, notes, source_url, and original_author.
     */
    func searchArtifacts(query: String, schemaFilter: String?) throws  -> [ArtifactRow]
    
    /**
     * Search manuscripts by title/body/notes substring (list-filter path;
     * palette search goes through the store FTS on the SharedStore surface).
     */
    func searchManuscripts(query: String, limit: UInt32?) throws  -> [ManuscriptRow]
    
    func searchPublications(query: String, parentId: String?, sortField: String, ascending: Bool, limit: UInt32?, offset: UInt32?) throws  -> [BibliographyRow]
    
    func setFlag(ids: [String], color: String?, style: String?, length: String?) throws  -> UndoInfo
    
    /**
     * Set the canonical_id field on an item (maps to CKRecord.recordID for CloudKit round-trip).
     * Bypasses the operation log — this is metadata for sync coordination.
     */
    func setItemCanonicalId(id: String, canonicalId: String) throws 
    
    /**
     * Set the origin field on an item (records which device created it).
     * Bypasses the operation log — this is metadata for sync coordination.
     */
    func setItemOrigin(id: String, origin: String) throws 
    
    func setLibraryDefault(id: String) throws 
    
    func setLocallyMaterialized(id: String, materialized: Bool) throws 
    
    /**
     * Save a manuscript body, optionally guarded by the last-known
     * `body_content_hash` (compare-and-set for cross-process safety).
     *
     * With `expected_hash = None` this is an unconditional save (legacy
     * behavior, matching imprint's setBody). With `Some(hash)`, the save is
     * rejected with `Conflict` when the stored hash differs — the caller
     * should re-read, reconcile (fast-forward or surface a conflict banner),
     * and retry.
     *
     * Note: the check-then-write runs as two store calls under this handle's
     * connection lock; a cross-process writer can still interleave in the
     * window between them. That residual race is closed by the Darwin
     * cross-process change notification + `absorbExternalChange` path
     * (GUI-meld Phase 4); the guard here catches the common stale-editor
     * case deterministically.
     */
    func setManuscriptBody(id: String, body: String, expectedHash: String?) throws  -> ManuscriptSaveOutcome
    
    func setPdfCloudAvailable(id: String, available: Bool) throws 
    
    func setRead(ids: [String], read: Bool) throws  -> UndoInfo
    
    func setStarred(ids: [String], starred: Bool) throws  -> UndoInfo
    
    /**
     * The sidebar's entire count sweep in one call: unread per container
     * (feeds AND libraries — see `SidebarCounts`) plus flag counts by
     * color. Replaces one FFI round-trip per feed + per library + per
     * color (~15 per sweep, the `snapshot` PerfMetrics budget breach)
     * with two grouped queries on the reader pool.
     *
     * The edge literal is the serde_json serialization of
     * `EdgeType::Contains` — the exact bytes `compile_query` binds for
     * `Predicate::ReferencedBy` — NOT a bare string. Matching those
     * semantics is what keeps this count equal to the point queries it
     * replaces.
     */
    func sidebarUnreadAndFlagCounts() throws  -> SidebarCounts
    
    /**
     * The allowed `manuscript.format` values (single source of truth in
     * impress-core). Swift's `DocumentFormat` asserts parity in tests.
     */
    func supportedManuscriptFormats()  -> [String]
    
    /**
     * Apply CKRecord deletions: `ref_...` names delete edges, item-UUID
     * names run the tombstone rule with `deleted_at = now`.
     */
    func syncApplyRemoteDeletions(recordNames: [String]) throws  -> SyncApplyReport
    
    /**
     * Merge fetched remote item records (whole-record LWW in Rust,
     * suppressed capture, FTS refreshed, manuscript conflict backups).
     */
    func syncApplyRemoteItems(records: [SyncItemRecord]) throws  -> SyncApplyReport
    
    /**
     * Apply fetched remote reference records; missing endpoints defer.
     */
    func syncApplyRemoteReferences(refs: [SyncReferenceRecord]) throws  -> SyncApplyReport
    
    /**
     * Apply fetched `ImpressTombstone` records (edit-after-delete
     * resurrects and re-pushes; ties → delete wins).
     */
    func syncApplyRemoteTombstones(tombstones: [SyncTombstoneRecord]) throws  -> SyncApplyReport
    
    /**
     * Local tombstones since `since_ms`, as wire records.
     */
    func syncLocalTombstones(sinceMs: Int64) throws  -> [SyncTombstoneRecord]
    
    /**
     * Read a sync-namespaced metadata value (`"sync."`-prefixed keys only).
     */
    func syncMetadataGet(key: String) throws  -> String?
    
    /**
     * Write (or clear, with `nil`) a sync-namespaced metadata value.
     */
    func syncMetadataSet(key: String, value: String?) throws 
    
    /**
     * Pending outbox entries in queue order (push cursor).
     */
    func syncOutboxEntries(limit: UInt32) throws  -> [SyncOutboxEntry]
    
    /**
     * Remove confirmed-pushed outbox rows by sequence number.
     */
    func syncOutboxRemove(seqs: [Int64]) throws 
    
    /**
     * Drop the archived system fields for a record.
     */
    func syncRecordStateDelete(recordName: String) throws 
    
    /**
     * Read the archived CKRecord system fields for a record, if any.
     */
    func syncRecordStateGet(recordName: String) throws  -> Data?
    
    /**
     * Archive CKRecord system fields for a record.
     */
    func syncRecordStateSet(recordName: String, blob: Data) throws 
    
    /**
     * Re-attempt all deferred references (call after each item batch).
     */
    func syncRetryPendingReferences() throws  -> SyncApplyReport
    
    /**
     * Snapshot outbox `item` entries into wire records (op items,
     * ephemeral rows and already-deleted rows are omitted).
     */
    func syncSnapshotItems(ids: [String]) throws  -> [SyncItemRecord]
    
    /**
     * Snapshot outbox `reference` entries (raw `src|tgt|edge` names) into
     * wire records with hashed `ref_` record names.
     */
    func syncSnapshotReferences(recordNames: [String]) throws  -> [SyncReferenceRecord]
    
    /**
     * Live sync queue depths (outbox / deferred refs / tombstones).
     */
    func syncStatusCounts() throws  -> SyncCounts
    
    /**
     * Undo all operations in a batch. Returns UndoInfo for the redo batch.
     */
    func undoBatch(batchId: String) throws  -> UndoInfo
    
    /**
     * Undo a single operation by ID. Returns UndoInfo for the inverse (redo) operation.
     */
    func undoOperation(operationId: String) throws  -> UndoInfo
    
    /**
     * Update an artifact's fields.
     */
    func updateArtifact(id: String, title: String?, sourceUrl: String?, notes: String?, artifactSubtype: String?, captureContext: String?, originalAuthor: String?, eventName: String?, eventDate: String?) throws  -> UndoInfo
    
    /**
     * Update a boolean payload field on any item.
     */
    func updateBoolField(id: String, field: String, value: Bool) throws  -> UndoInfo
    
    func updateComment(id: String, text: String) throws 
    
    /**
     * Persist a re-anchored range for an existing comment.
     *
     * Called after `reanchor_comment` resolves a Moved range against a new
     * body: stores the new byte offsets plus the `body_content_hash` they
     * are valid against. Leaves `anchor_text` unchanged (it is the original
     * snippet and remains the search key for future re-anchoring).
     */
    func updateCommentAnchor(commentId: String, anchorStart: Int64, anchorEnd: Int64, anchoredBodyHash: String) throws 
    
    func updateField(id: String, field: String, value: String?) throws  -> UndoInfo
    
    /**
     * Update an integer payload field on any item.
     */
    func updateIntField(id: String, field: String, value: Int64?) throws  -> UndoInfo
    
    /**
     * Update tag definition colors.
     */
    func updateTag(path: String, colorLight: String?, colorDark: String?) throws 
    
}

/**
 * The main entry point for Swift. Wraps SqliteItemStore + SchemaRegistry.
 */
open class ImbibStore:
    ImbibStoreProtocol {
    fileprivate let pointer: UnsafeMutableRawPointer!

    /// Used to instantiate a [FFIObject] without an actual pointer, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoPointer {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
    required public init(unsafeFromRawPointer pointer: UnsafeMutableRawPointer) {
        self.pointer = pointer
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noPointer: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing [Pointer] the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noPointer: NoPointer) {
        self.pointer = nil
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiClonePointer() -> UnsafeMutableRawPointer {
        return try! rustCall { uniffi_imbib_core_fn_clone_imbibstore(self.pointer, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        guard let pointer = pointer else {
            return
        }

        try! rustCall { uniffi_imbib_core_fn_free_imbibstore(pointer, $0) }
    }

    
    /**
     * Open or create a store at the given database path.
     */
public static func `open`(path: String)throws  -> ImbibStore {
    return try  FfiConverterTypeImbibStore.lift(try rustCallWithError(FfiConverterTypeStoreApiError.lift) {
    uniffi_imbib_core_fn_constructor_imbibstore_open(
        FfiConverterString.lower(path),$0
    )
})
}
    
    /**
     * Open an in-memory store (for testing).
     */
public static func openInMemory()throws  -> ImbibStore {
    return try  FfiConverterTypeImbibStore.lift(try rustCallWithError(FfiConverterTypeStoreApiError.lift) {
    uniffi_imbib_core_fn_constructor_imbibstore_open_in_memory($0
    )
})
}
    

    
