        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AttachmentSignal, into buf: inout [UInt8]) {
        switch value {
        
        
        case .declaredFileField:
            writeInt(&buf, Int32(1))
        
        
        case .citeKey:
